package net.jqwik.docs;

import net.jqwik.api.*;

class ShrinkingFilterExamples {

	@Property(afterFailure = AfterFailureMode.RANDOM_SEED)
	// Different seeds result in different shrinking results
	boolean shrinkingCanTakeAWhile(@ForAll("first") String first, @ForAll("second") String second) {
		String aString = first + second;
		return aString.length() > 5 || aString.length() < 4;
	}

	@Provide
	Arbitrary<String> first() {
		return Arbitraries.strings()
						  .withCharRange('a', 'z')
						  .ofMinLength(1)
						  .ofMaxLength(10)
						  .filter(string -> string.endsWith("h"));
	}

	@Provide
	Arbitrary<String> second() {
		return Arbitraries.strings()
						  .withCharRange('0', '9')
						  .ofMinLength(0)
						  .ofMaxLength(10)
						  .filter(string -> string.length() >= 1);
	}

	@Property(afterFailure = AfterFailureMode.RANDOM_SEED)
	boolean shouldShrinkToBAH(@ForAll("aVariableString") String aString) {
		return aString.length() > 4 || aString.length() < 3;
	}

	@Provide()
	Arbitrary<String> aVariableString() {
		return Arbitraries.strings()
						  .withCharRange('a', 'z')
						  .ofMinLength(1)
						  .ofMaxLength(10)
						  .filter(string -> string.endsWith("h"))
						  .filter(string -> string.charAt(0) > 'a');
	}

	@Property(afterFailure = AfterFailureMode.RANDOM_SEED)
	boolean withAssumption_shouldShrinkToCCH(@ForAll("aVariableString") String aString) {
		Assume.that(!aString.contains("a") && !aString.contains("b"));
		return aString.length() > 4 || aString.length() < 3;
	}

}

package net.jqwik.engine.properties.stateful;

import java.util.*;
import java.util.function.*;

import net.jqwik.api.*;
import net.jqwik.api.constraints.*;
import net.jqwik.api.lifecycle.*;
import net.jqwik.api.stateful.*;
import net.jqwik.testing.*;

import static org.assertj.core.api.Assertions.*;

import static net.jqwik.testing.ShrinkingSupport.*;

@SuppressWarnings("unchecked")
class ActionSequenceShrinkingTests {

	@Property(afterFailure = AfterFailureMode.RANDOM_SEED)
	@ExpectFailure(checkResult = FailedAndShrunkToAddX.class, failureType = AssertionError.class)
	void dontShrinkToActionsWithOnlyFailingPreconditions(@ForAll("addXorY") @Size(3) ActionSequence<String> sequence) {
		String model = sequence.run("");
		assertThat(model).isEmpty();
	}

	private class FailedAndShrunkToAddX implements Consumer<PropertyExecutionResult> {
		@SuppressWarnings({"unchecked", "OptionalGetWithoutIsPresent"})
		@Override
		public void accept(PropertyExecutionResult result) {
			assertThat(result.falsifiedParameters()).isPresent();
			assertThat(result.throwable()).isPresent();
			assertThat(result.throwable().get()).isInstanceOf(AssertionError.class);

			List<Object> sample = result.falsifiedParameters().get();
			assertThat(sample).hasSize(1);

			ActionSequence<String> sequence = (ActionSequence<String>) sample.get(0);
			assertThat(sequence.runActions()).hasSize(1);
			assertThat(sequence.runActions().get(0).toString()).isEqualTo("addX");
		}
	}

	@Provide
	Arbitrary<ActionSequence<String>> addXorY() {
		return Arbitraries.sequences(
			Arbitraries.oneOf(addX(), addYIfNotEmpty())
		);
	}

	@Example
	void sequencesAreShrunkToSingleAction(@ForAll Random random) {
		Arbitrary<ActionSequence<String>> arbitrary = Arbitraries.sequences(addX());
		Shrinkable<ActionSequence<String>> shrinkable = arbitrary.generator(1000, true).next(random);
		shrinkable.value().run(""); // to setup sequence

		TestingFalsifier<ActionSequence<String>> falsifier = (ActionSequence<String> seq) -> {
			seq.run("");
			return false;
		};

		ActionSequence<String> shrunkValue = shrink(shrinkable, falsifier, null);

		assertThat(shrunkValue.runActions()).hasSize(1);
		assertThat(shrunkValue.run("")).isEqualTo("x");
	}

	@Example
	void dontShrinkBelow1Action(@ForAll Random random) {
		Arbitrary<ActionSequence<String>> arbitrary = Arbitraries.sequences(addX());
		Shrinkable<ActionSequence<String>> shrinkable = arbitrary.generator(1000, true).next(random);
		shrinkable.value().run(""); // to setup sequence

		TestingFalsifier<ActionSequence<String>> falsifier = (ActionSequence<String> seq) -> {
			seq.run("");
			throw failAndCatch(null);
		};

		ActionSequence<String> shrunkValue = shrink(shrinkable, falsifier, failAndCatch(null));

		assertThat(shrunkValue.runActions()).hasSize(1);
	}

	@Example
	void remainingActionsAreShrunkThemselves(@ForAll Random random) {
		Arbitrary<ActionSequence<String>> arbitrary = Arbitraries.sequences(addStringOfLength2());
		Shrinkable<ActionSequence<String>> shrinkable = arbitrary.generator(1000, true).next(random);
		shrinkable.value().run(""); // to setup sequence

		TestingFalsifier<ActionSequence<String>> falsifier = (ActionSequence<String> seq) -> {
			seq.run("");
			return false;
		};

		ActionSequence<String> shrunkValue = shrink(shrinkable, falsifier, null);

		assertThat(shrunkValue.runActions()).hasSize(1);
		assertThat(shrunkValue.runActions().get(0).run("")).isIn("aa", "AA");
	}

	private Arbitrary<Action<String>> addX() {
		return Arbitraries.just(new Action<String>() {
			@Override
			public String run(final String model) {
				return model + "x";
			}

			@Override
			public String toString() {
				return "addX";
			}
		});
	}

	private Arbitrary<Action<String>> addYIfNotEmpty() {
		return Arbitraries.just(new Action<String>() {
			@Override
			public boolean precondition(final String state) {
				return !state.isEmpty();
			}

			@Override
			public String run(final String model) {
				return model + "y";
			}

			@Override
			public String toString() {
				return "addYIfNotEmpty";
			}
		});
	}

	private Arbitrary<Action<String>> addStringOfLength2() {
		return Arbitraries.strings().alpha().ofLength(2).map(s -> model -> model + s);
	}

	private AssertionError failAndCatch(String message) {
		try {
			throw new AssertionError(message);
		} catch (AssertionError error) {
			return error;
		}
	}


}

import type { AsyncCommand } from './command/AsyncCommand.js';
import type { Command } from './command/Command.js';
import type { ICommand } from './command/ICommand.js';
import type { Scheduler } from '../../arbitrary/scheduler.js';
import { scheduleCommands } from './commands/ScheduledCommand.js';

/**
 * Synchronous definition of model and real
 * @remarks Since 2.2.0
 * @public
 */
export type ModelRunSetup<Model, Real> = () => { model: Model; real: Real };

/**
 * Asynchronous definition of model and real
 * @remarks Since 2.2.0
 * @public
 */
export type ModelRunAsyncSetup<Model, Real> = () => Promise<{ model: Model; real: Real }>;

type SetupFun<Model, Real, P> = (s: { model: Model; real: Real }) => P;
interface SetupProducer<Model, Real, P> {
  then: (fun: SetupFun<Model, Real, P>) => P;
}

const genericModelRun = <Model extends object, Real, P, CheckAsync extends boolean>(
  s: SetupProducer<Model, Real, P>,
  cmds: Iterable<ICommand<Model, Real, P, CheckAsync>>,
  initialValue: P,
  runCmd: (cmd: ICommand<Model, Real, P, CheckAsync>, m: Model, r: Real) => P,
  then: (p: P, c: () => P | undefined) => P,
): P => {
  return s.then((o: { model: Model; real: Real }) => {
    const { model, real } = o;
    let state = initialValue;
    for (const c of cmds) {
      state = then(state, () => {
        // No need to check incoming state
        // as c.run "throws" in case of exception
        return runCmd(c, model, real);
      });
    }
    return state;
  });
};

const internalModelRun = <Model extends object, Real>(
  s: ModelRunSetup<Model, Real>,
  cmds: Iterable<Command<Model, Real>>,
): void => {
  const then = (_p: undefined, c: () => undefined) => c();
  const setupProducer: SetupProducer<Model, Real, undefined> = {
    then: (fun: SetupFun<Model, Real, void>) => {
      fun(s());
      return undefined;
    },
  };
  const runSync = (cmd: Command<Model, Real>, m: Model, r: Real) => {
    if (cmd.check(m)) cmd.run(m, r);
    return undefined;
  };
  return genericModelRun(
    setupProducer,
    cmds as Iterable<ICommand<Model, Real, undefined, false>>,
    undefined,
    runSync,
    then,
  );
};

const isAsyncSetup = <Model, Real>(
  s: ReturnType<ModelRunSetup<Model, Real>> | ReturnType<ModelRunAsyncSetup<Model, Real>>,
): s is ReturnType<ModelRunAsyncSetup<Model, Real>> => {
  return typeof (s as any).then === 'function';
};

const internalAsyncModelRun = async <Model extends object, Real, CheckAsync extends boolean>(
  s: ModelRunSetup<Model, Real> | ModelRunAsyncSetup<Model, Real>,
  cmds: Iterable<AsyncCommand<Model, Real, CheckAsync>>,
  defaultPromise = Promise.resolve(),
): Promise<void> => {
  const then = (p: Promise<void>, c: () => Promise<void> | undefined) => p.then(c);
  const setupProducer = {
    then: (fun: SetupFun<Model, Real, Promise<void>>) => {
      const out = s();
      if (isAsyncSetup(out)) return out.then(fun);
      else return fun(out);
    },
  };
  const runAsync = async (cmd: AsyncCommand<Model, Real, CheckAsync>, m: Model, r: Real) => {
    if (await cmd.check(m)) await cmd.run(m, r);
  };
  return await genericModelRun(setupProducer, cmds, defaultPromise, runAsync, then);
};

/**
 * Run synchronous commands over a `Model` and the `Real` system
 *
 * Throw in case of inconsistency
 *
 * @param s - Initial state provider
 * @param cmds - Synchronous commands to be executed
 *
 * @remarks Since 1.5.0
 * @public
 */
export function modelRun<Model extends object, Real, InitialModel extends Model>(
  s: ModelRunSetup<InitialModel, Real>,
  cmds: Iterable<Command<Model, Real>>,
): void {
  internalModelRun(s, cmds);
}

/**
 * Run asynchronous commands over a `Model` and the `Real` system
 *
 * Throw in case of inconsistency
 *
 * @param s - Initial state provider
 * @param cmds - Asynchronous commands to be executed
 *
 * @remarks Since 1.5.0
 * @public
 */
export async function asyncModelRun<Model extends object, Real, CheckAsync extends boolean, InitialModel extends Model>(
  s: ModelRunSetup<InitialModel, Real> | ModelRunAsyncSetup<InitialModel, Real>,
  cmds: Iterable<AsyncCommand<Model, Real, CheckAsync>>,
): Promise<void> {
  await internalAsyncModelRun(s, cmds);
}

/**
 * Run asynchronous and scheduled commands over a `Model` and the `Real` system
 *
 * Throw in case of inconsistency
 *
 * @param scheduler - Scheduler
 * @param s - Initial state provider
 * @param cmds - Asynchronous commands to be executed
 *
 * @remarks Since 1.24.0
 * @public
 */
export async function scheduledModelRun<
  Model extends object,
  Real,
  CheckAsync extends boolean,
  InitialModel extends Model,
>(
  scheduler: Scheduler,
  s: ModelRunSetup<InitialModel, Real> | ModelRunAsyncSetup<InitialModel, Real>,
  cmds: Iterable<AsyncCommand<Model, Real, CheckAsync>>,
): Promise<void> {
  const scheduledCommands = scheduleCommands(scheduler, cmds);
  const out = internalAsyncModelRun(s, scheduledCommands, scheduler.schedule(Promise.resolve(), 'startModel'));
  await scheduler.waitFor(out);
  await scheduler.waitAll();
}

import { describe, it, expect } from 'vitest';
import * as fc from '../src/fast-check.js';
import { assertAndGetRunDetails } from './__test-helpers__/AssertAndGetRunDetails.js';
import { seed } from './seed.js';

describe(`ReplayFailures (seed: ${seed})`, () => {
  const propArbitrary = fc.uniqueArray(fc.string());
  const propCheck = (data: string[]) => {
    // element at <idx> should not contain the first character of the element just before
    // 01, 12, 20  - is correct
    // 01, 12, 21  - is not
    if (data.length === 0) return true;
    for (let idx = 1; idx < data.length; ++idx) {
      if (data[idx].indexOf(data[idx - 1][0]) !== -1) return false;
    }
    return true;
  };
  const prop = fc.property(propArbitrary, propCheck);

  describe('fc.sample', () => {
    it('Should rebuild counterexample using sample and (path, seed)', async () => {
      const out = await assertAndGetRunDetails(prop, { seed: seed });
      expect(out.failed).toBe(true);
      expect(fc.sample(propArbitrary, { seed: seed, path: out.counterexamplePath!, numRuns: 1 })).toEqual(
        out.counterexample,
      );
    });
    it('Should rebuild the whole shrink path using sample', async () => {
      const failuresRecorded: string[][] = [];
      const out = await assertAndGetRunDetails(
        fc.property(propArbitrary, (data) => {
          if (propCheck(data)) return true;
          failuresRecorded.push(data);
          return false;
        }),
        { seed: seed },
      );
      expect(out.failed).toBe(true);

      const replayedFailures = [];
      const segments = out.counterexamplePath!.split(':');
      for (let idx = 1; idx !== segments.length + 1; ++idx) {
        const p = segments.slice(0, idx).join(':');
        const g = fc.sample(propArbitrary, { seed: seed, path: p, numRuns: 1 });
        replayedFailures.push(g[0]);
      }
      expect(replayedFailures).toEqual(failuresRecorded);
    });
  });
  describe('fc.assert', () => {
    it('Should start from the minimal counterexample given its path', async () => {
      const out = await assertAndGetRunDetails(prop, { seed: seed });
      expect(out.failed).toBe(true);

      let numCalls = 0;
      let numValidCalls = 0;
      let validCallIndex = -1;
      const out2 = await assertAndGetRunDetails(
        fc.property(propArbitrary, (data) => {
          try {
            expect(data).toEqual(out.counterexample![0]);
            validCallIndex = numCalls;
            ++numValidCalls;
          } catch {
            // noop
          }
          ++numCalls;
          return propCheck(data);
        }),
        { seed: seed, path: out.counterexamplePath! },
      );
      expect(numValidCalls).toEqual(1);
      expect(validCallIndex).toEqual(0);
      expect(out2.numRuns).toEqual(1);
      expect(out2.numShrinks).toEqual(0);
      expect(out2.counterexamplePath).toEqual(out.counterexamplePath);
      expect(out2.counterexample).toEqual(out.counterexample);
    });
    it('Should start from any position in the path', async () => {
      const out = await assertAndGetRunDetails(prop, { seed: seed });
      expect(out.failed).toBe(true);

      const segments = out.counterexamplePath!.split(':');
      for (let idx = 1; idx !== segments.length + 1; ++idx) {
        const p = segments.slice(0, idx).join(':');
        const outMiddlePath = await assertAndGetRunDetails(prop, { seed: seed, path: p });
        expect(outMiddlePath.numRuns).toEqual(1);
        expect(outMiddlePath.numShrinks).toEqual(out.numShrinks - idx + 1);
        expect(outMiddlePath.counterexamplePath).toEqual(out.counterexamplePath);
        expect(outMiddlePath.counterexample).toEqual(out.counterexample);
      }
    });
    it('Should only execute one test given path for failure and noShrink flag', async () => {
      const out = await assertAndGetRunDetails(prop, { seed: seed });
      expect(out.failed).toBe(true);

      const segments = out.counterexamplePath!.split(':');
      for (let idx = 1; idx !== segments.length + 1; ++idx) {
        const p = segments.slice(0, idx).join(':');
        const outMiddlePath = await assertAndGetRunDetails(prop, { seed: seed, path: p, endOnFailure: true });
        expect(outMiddlePath.numRuns).toEqual(1);
        expect(outMiddlePath.numShrinks).toEqual(0);
        expect(outMiddlePath.counterexamplePath).toEqual(p);
      }
    });
    it('Should take initial path into account when computing path', async () => {
      const out = await assertAndGetRunDetails(prop, { seed: seed });
      expect(out.failed).toBe(true);

      const segments = out.counterexamplePath!.split(':');
      const playOnIndex = (seed >>> 0) % segments.length; // seed could be <0

      for (let offset = 0; offset !== +segments[playOnIndex]; ++offset) {
        const p = [...segments.slice(0, playOnIndex), offset].join(':');
        const outMiddlePath = await assertAndGetRunDetails(prop, { seed: seed, path: p });
        expect(outMiddlePath.counterexamplePath).toEqual(out.counterexamplePath);
        expect(outMiddlePath.counterexample).toEqual(out.counterexample);
      }
    });
    it('Should print the rejected path when unable to replay for path', async () => {
      await fc.assert(
        fc.property(
          fc.integer(),
          fc.array(fc.nat({ max: 100 }), { minLength: 3 }).map((elements) => elements.join(':')),
          (internalSeed, path) => {
            // Sync throw!!!
            expect(() =>
              assertAndGetRunDetails(
                fc.property(fc.constant(0), () => {}), // no shrink available on constant, our path should break
                { seed: internalSeed, path },
              ),
            ).toThrowError(new RegExp(`wrong path=${path}`));
          },
        ),
        { seed },
      );
    });
    it('Should print the rejected path when unable to replay for path on sample', async () => {
      await fc.assert(
        fc.property(
          fc.integer(),
          fc.array(fc.nat({ max: 100 }), { minLength: 3 }).map((elements) => elements.join(':')),
          (internalSeed, path) => {
            expect(() =>
              fc.sample(
                fc.constant(0), // no shrink available on constant, our path should break
                { seed: internalSeed, path },
              ),
            ).toThrowError(new RegExp(`wrong path=${path}`));
          },
        ),
        { seed },
      );
    });
  });
});
